const nextFreeEanCode = `-- name: NextFreeEanCode :one
SELECT es.start_code
FROM ean_series es
WHERE es.archived = false
  AND es.start_code NOT IN (
    SELECT p.ean_code FROM products p WHERE p.ean_code IS NOT NULL AND p.ean_code != ''
  )
ORDER BY es.start_code
LIMIT 1
`

// REG-04: suggest the next free EAN code for a product
func (q *Queries) NextFreeEanCode(ctx context.Context) (string, error) {
	row := q.db.QueryRow(ctx, nextFreeEanCode)
	var start_code string
	err := row.Scan(&start_code)
	return start_code, err
}

