const topProductsByCustomer = `-- name: TopProductsByCustomer :many
SELECT ol.product_id, p.name, SUM(ol.quantity) AS total_quantity
FROM order_lines ol
JOIN orders o ON o.id = ol.order_id AND o.customer_id = $1 AND o.archived = false
JOIN products p ON p.id = ol.product_id AND p.archived = false
WHERE ol.archived = false
GROUP BY ol.product_id, p.name
ORDER BY total_quantity DESC
LIMIT 10
`

type TopProductsByCustomerRow struct {
	ProductID     uuid.UUID `json:"product_id"`
	Name          string    `json:"name"`
	TotalQuantity int64     `json:"total_quantity"`
}

// KUN-04: most purchased products per customer
func (q *Queries) TopProductsByCustomer(ctx context.Context, customerID uuid.UUID) ([]TopProductsByCustomerRow, error) {
	rows, err := q.db.Query(ctx, topProductsByCustomer, customerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TopProductsByCustomerRow
	for rows.Next() {
		var i TopProductsByCustomerRow
		if err := rows.Scan(&i.ProductID, &i.Name, &i.TotalQuantity); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

